	if b == nil {
		return errNilBlob
	}
	if b.SignedBlockHeader == nil || b.SignedBlockHeader.Header == nil {
		return errNilBlockHeader
	}
	if len(b.SignedBlockHeader.Signature) == 0 {
		return errMissingBlockSignature
	}
	return nil
}

